        "chapter": "chapter10",
        "classes": [
            "class4-rest",
            "class4-unrest"
        ],
        "question": "What should be checked about visible wheel lugs?",
        "options": {
            "A": "They are coated with oil",
            "B": "They are all different sizes",
            "C": "They can be turned by hand",
            "D": "They are secure and none are missing, broken or loose"
        },
